Method.Source:
/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <returns>NoYes</returns>
static NoYes getUseCompressedData()
{
    NoYes       useLastCompressedData;
    ;
    changecompany(NDXUmsatzParametersGlobal::find().CompanyMaster)
    {
        useLastCompressedData = NDXUmsatzParameters::find().useLastCompressedData;
    }
    return useLastCompressedData;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "l_forupdate">boolean</param>
/// <returns>NDXUmsatzParametersGlobal</returns>
static NDXUmsatzParametersGlobal find(boolean l_forupdate = false)
{
    NDXUmsatzParametersGlobal parameter;

    parameter.selectForUpdate(l_forupdate);

    select firstonly parameter
    index KeyIdx
    where parameter.key == 0;

    if (!parameter && !parameter.isTmp())
    {
        Company::createParameter(parameter);
    }

    return parameter;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <returns>utcdatetime</returns>
public static utcdatetime getDateClose()
{
    NDXUmsatzParameters nDXUmsatzParameters;
    ;
    nDXUmsatzParameters = NDXUmsatzParametersGlobal::findParametersMaster();
    if (nDXUmsatzParameters.lastClose > nDXUmsatzParameters.BasisDate4Close)
    {
        return nDXUmsatzParameters.BasisDate4Close;
    }
    else
    {
        // Passiert während der Abschlussarbeiten
        // Abschlussdatum wurde hochgesetzt, die Daten sind aber für den neuen Monat noch nicht nutzbar
        return DateTimeUtil::addMonths(nDXUmsatzParameters.BasisDate4Close, -1);
    }

}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <returns>NDXUmsatzParameters</returns>
static NDXUmsatzParameters findParametersMaster()
{
    NDXUmsatzParameters     nDXUmsatzParameters;        
    ;
    changecompany(NDXUmsatzParametersGlobal::find().CompanyMaster)
    {
        nDXUmsatzParameters = null;
        nDXUmsatzParameters = nDXUmsatzParameters::find();
    }
    return nDXUmsatzParameters;
}

